"""Build the shipped case corpus, with expected output generated by the engine.

Run from the repo root:

    python services/engine/scripts/sync_cases.py

The corpus is committed, not built at runtime, for three reasons: the web app can import it
into a Vercel bundle, `tests/test_golden.py` can prove it still matches the engine, and a
reviewer can read exactly what the tool produces on a real scenario without running anything.

Cases are authored here as Python literals because the tick arithmetic - anchors, drift,
budget windows - has to be derived, not typed. Hand-writing 4096 anchors in JSON would be a
way of introducing typos.
"""

from __future__ import annotations

import json
import sys
from collections.abc import Iterable
from pathlib import Path
from typing import Any, NamedTuple

REPO_ROOT = Path(__file__).resolve().parents[3]
sys.path.insert(0, str(REPO_ROOT / "services" / "engine" / "src"))

from tickrate_sim import (  # noqa: E402 - path bootstrap must precede the import
    budget_profile,
    diff_tables,
    parse_table,
    parse_trace,
    replay,
    tickrate_stats,
    validate_table,
)

DATA = REPO_ROOT / "apps" / "web" / "data"

#: 64 Hz is 15.625 ms per tick.
MS_PER_TICK_64 = 1000.0 / 64.0


class AnchorRate(NamedTuple):
    """How a trace's wall-clock anchors are sampled.

    One stamp every `stride` ticks, at `ms_per_tick` milliseconds per tick. Both halves matter
    and neither can be inferred from the other: a stride of 64 ticks against a 58 Hz clock is
    a server that is nine percent slow, which is a different scenario from a different stride.
    """

    stride: int
    ms_per_tick: float = MS_PER_TICK_64


#: A server hitting its declared 64 Hz.
ON_RATE = AnchorRate(64)
#: A server provisioned for 64 Hz and delivering 58: 1000/58 ms per tick, sampled every 64 ticks.
DRIFTED = AnchorRate(64, 1000.0 / 58.0)

#: Either an anchor sampling rate, or explicit anchors.
Anchors = AnchorRate | list[dict[str, int]]


def state(name: str, *, terminal: bool = False, description: str = "") -> dict[str, Any]:
    return {"name": name, "terminal": terminal, "description": description}


def rule(
    rule_id: str,
    source: str,
    target: str,
    *,
    min_ticks: int = 0,
    max_ticks: int | None = None,
    repeatable: bool = True,
    guard: str = "",
) -> dict[str, Any]:
    return {
        "id": rule_id,
        "source": source,
        "target": target,
        "minTicks": min_ticks,
        "maxTicks": max_ticks,
        "repeatable": repeatable,
        "guard": guard,
    }


def anchors_for(ticks: Iterable[int], ms_per_tick: float = MS_PER_TICK_64) -> list[dict[str, int]]:
    """Millisecond stamps derived from tick numbers, so anchors cannot drift from the rate."""
    return [{"tick": tick, "ms": int(round(tick * ms_per_tick))} for tick in ticks]


