# ------------------------------------------------------------------ traces


def trace(
    trace_id: str,
    events: list[tuple[int, str]],
    *,
    end_tick: int,
    rate: Anchors = ON_RATE,
) -> dict[str, Any]:
    """One shipped trace. `rate` is either a tick stride or explicit anchors.

    Anchors are derived from the rate rather than typed, so a change to the declared tickrate
    cannot leave stale millisecond values behind in the committed corpus.
    """
    return {
        "id": trace_id,
        "tableId": "skirmish-64",
        "startTick": 0,
        "endTick": end_tick,
        "events": [{"tick": tick, "target": target, "note": ""} for tick, target in events],
        "anchors": (
            anchors_for(range(0, end_tick + 1, rate.stride), rate.ms_per_tick)
            if isinstance(rate, AnchorRate)
            else rate
        ),
    }


def jitter_anchors(steps: int = 160) -> list[dict[str, int]]:
    """Alternating 50 ms / 75 ms frame gaps, on average exactly a 64 Hz budget.

    Anchors sit every 4 ticks, where 4 ticks of a 64 Hz server is 62.5 ms. The clock
    alternates +50 ms and +75 ms, and 50 + 75 = 125 ms for 8 ticks - so the *mean* rate is
    exactly 62.5 Hz per tick while no single 4-tick interval ever is (it reads 80 Hz, then
    53.3 Hz, then 80 Hz). This is the case that separates "the average looks fine" from "the
    server is healthy", and it is why the engine reports jitter alongside the mean rather
    than instead of it.
    """
    stamps: list[dict[str, int]] = [{"tick": 0, "ms": 0}]
    clock = 0
    for index in range(steps):
        clock += 50 if index % 2 == 0 else 75
        stamps.append({"tick": (index + 1) * 4, "ms": clock})
    return stamps


#: Sampling every 64 ticks gives one anchor per second of a 64 Hz match - dense enough for a
#: drift figure to mean something, sparse enough that a reviewer can read the JSON.
ONCE_PER_SECOND = list(range(0, 7681, 64))

