TABLES = [SKIRMISH_64, SKIRMISH_64_R2, SKIRMISH_BROKEN]


def build() -> dict[str, Any]:
    """Compute every expected result from the engine itself.

    The corpus is emitted as the *authored* documents, but every engine call goes through
    `parse_table` / `parse_trace` first. That is not ceremony: it means the committed fixtures
    were produced through the same boundary a real caller uses, so a parser change shows up
    here instead of in production.
    """
    documents = {table["id"]: table for table in TABLES}
    tables = {name: parse_table(document) for name, document in documents.items()}
    diff = diff_tables(tables["skirmish-64"], tables["skirmish-64-r2"])

    cases = []
    for case in CASES:
        table_name = case["trace"]["tableId"]
        table = tables[table_name]
        trace = parse_trace(case["trace"])
        cases.append(
            {
                **case,
                "table": documents[table_name],
                "expected": {
                    "replay": replay(table, trace),
                    "budgetProfile": budget_profile(table, trace),
                    "tickrate": tickrate_stats(table, trace),
                },
            }
        )

    return {
        "tables": TABLES,
        "cases": cases,
        "tableDiffs": [
            {
                "id": "skirmish-64-vs-r2",
                "title": "skirmish-64 to skirmish-64-r2",
                "before": documents["skirmish-64"],
                "after": documents["skirmish-64-r2"],
                "expected": diff,
            }
        ],
        "tableChecks": [
            {
                "id": table["id"],
                "title": f"Structural check of {table['id']}",
                "table": table,
                "expected": validate_table(tables[table["id"]]),
            }
            for table in TABLES
        ],
    }


def write(path: Path, payload: Any) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    text = json.dumps(payload, indent=2, sort_keys=False) + "\n"
    path.write_text(text, encoding="utf8", newline="\n")
    print(f"wrote {path.relative_to(REPO_ROOT)} ({len(text)} bytes)")


def main() -> int:
    payload = build()
    write(DATA / "tables.json", payload["tables"])
    write(DATA / "cases.json", payload["cases"])
    write(DATA / "table-diffs.json", payload["tableDiffs"])
    write(DATA / "table-checks.json", payload["tableChecks"])
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
